+	}
+	if !s.started {
+		return errors.New("session not started")
+	}
+
+	startAt := time.Now()
+
+	if hooks != nil && hooks.OnExecuteInit != nil {
+		hooks.OnExecuteInit(s.config.Session)
+	}
