+	envDumpEndMarker   = "__EXECD_ENV_DUMP_END_8a3f__"
+	exitMarkerPrefix   = "__EXECD_EXIT_v1__:"
+	pwdMarkerPrefix    = "__EXECD_PWD_v1__:"
