+// Start launches an interactive bash process for WebSocket stdin/stdout mode.
+// It is idempotent: if the process is already running, it returns nil.
+// Unlike run(), this bash process stays alive reading from stdin until closed.
+func (s *bashSession) Start() error {
+	s.mu.Lock()
+	if s.wsPid != 0 {
+		s.mu.Unlock()
+		return nil // already running
+	}
+	if s.closing {
+		s.mu.Unlock()
+		return errors.New("session is closing")
+	}
+	s.mu.Unlock()
+
+	cmd := exec.Command("bash", "--noprofile", "--norc")
+	if s.cwd != "" {
+		cmd.Dir = s.cwd
+	}
+	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
+
+	stdinR, stdinW, err := os.Pipe()
+	if err != nil {
+		return fmt.Errorf("create stdin pipe: %w", err)
+	}
+	stdoutR, stdoutW, err := os.Pipe()
+	if err != nil {
+		_ = stdinR.Close()
+		_ = stdinW.Close()
+		return fmt.Errorf("create stdout pipe: %w", err)
+	}
+	stderrR, stderrW, err := os.Pipe()
+	if err != nil {
+		_ = stdinR.Close()
+		_ = stdinW.Close()
+		_ = stdoutR.Close()
+		_ = stdoutW.Close()
+		return fmt.Errorf("create stderr pipe: %w", err)
+	}
+
+	cmd.Stdin = stdinR
+	cmd.Stdout = stdoutW
+	cmd.Stderr = stderrW
+
+	if err := cmd.Start(); err != nil {
+		_ = stdinR.Close()
+		_ = stdinW.Close()
+		_ = stdoutR.Close()
+		_ = stdoutW.Close()
+		_ = stderrR.Close()
+		_ = stderrW.Close()
+		return fmt.Errorf("start bash: %w", err)
+	}
+
+	// Close child-side ends in the parent process.
+	_ = stdinR.Close()
+	_ = stdoutW.Close()
+	_ = stderrW.Close()
+
+	doneCh := make(chan struct{})
+
+	s.mu.Lock()
+	// Reset stale PTY state so WriteStdin targets the correct pipe on mode switch.
+	s.isPTY = false
+	s.ptmx = nil
+	s.stdin = stdinW
+	s.doneCh = doneCh
+	s.wsPid = cmd.Process.Pid
+	s.started = true
+	s.mu.Unlock()
+
+	// Broadcast goroutine: reads real stdout and fans out to the current per-connection sink.
+	go func() {
+		buf := make([]byte, 32*1024)
+		for {
+			n, err := stdoutR.Read(buf)
+			if n > 0 {
+				s.outMu.Lock()
+				w := s.stdoutW
+				s.outMu.Unlock()
+				if w != nil {
+					_, _ = w.Write(buf[:n])
+				}
+			}
+			if err != nil {
+				s.outMu.Lock()
+				if s.stdoutW != nil {
+					_ = s.stdoutW.Close()
+					s.stdoutW = nil
+				}
+				s.outMu.Unlock()
+				return
+			}
+		}
+	}()
+
+	// Broadcast goroutine: reads real stderr and fans out to the current per-connection sink.
+	go func() {
+		buf := make([]byte, 32*1024)
+		for {
+			n, err := stderrR.Read(buf)
+			if n > 0 {
+				s.outMu.Lock()
+				w := s.stderrW
+				s.outMu.Unlock()
+				if w != nil {
+					_, _ = w.Write(buf[:n])
+				}
+			}
+			if err != nil {
+				s.outMu.Lock()
+				if s.stderrW != nil {
+					_ = s.stderrW.Close()
+					s.stderrW = nil
+				}
+				s.outMu.Unlock()
+				return
+			}
+		}
+	}()
+
+	go func() {
+		_ = cmd.Wait()
+		code := -1
+		if cmd.ProcessState != nil {
+			code = cmd.ProcessState.ExitCode()
+		}
+		_ = stdinW.Close()
+		s.mu.Lock()
+		s.lastExitCode = code
+		s.wsPid = 0
+		s.mu.Unlock()
+		close(doneCh)
+	}()
+
+	return nil
+}
