body:
`completeCh` is only closed from `OnExecuteComplete`. For runtimes that emit only `OnExecuteError` on failure (e.g., non-zero exit), this means the handler will always wait the full graceful shutdown timeout even though the final SSE frame has already been flushed. Consider also signaling completion from `OnExecuteError` (and guarding the close with `sync.Once` to avoid panics if multiple terminal callbacks fire).
```suggestion
	// completeCh is closed when a terminal callback fires, meaning the final SSE
	// event has been written and flushed. We only wait for this callback as a
	// safety check and then return immediately to avoid fixed tail latency.
	completeCh := make(chan struct{})
	var completeOnce sync.Once
	complete := func() {
		completeOnce.Do(func() {
			close(completeCh)
		})
	}
	origComplete := eventsHandler.OnExecuteComplete
	eventsHandler.OnExecuteComplete = func(executionTime time.Duration) {
		if origComplete != nil {
			origComplete(executionTime)
		}
		complete()
	}
	origError := eventsHandler.OnExecuteError
	eventsHandler.OnExecuteError = func(err error) {
		if origError != nil {
			origError(err)
		}
		complete()
	}
